						char = char + (rt.Popcnt32((b & rt.Bitmask8(rt.GtS8(w, rt.Splat8(0xffffffbf))))) + rt.Popcnt32((b & rt.Bitmask8(rt.GeU8(w, rt.Splat8(240))))))
